def esc(value: object) -> str: return html.escape(str(value), quote=True)
def route(lang: str, suffix: str = "") -> str: return ("/en/" if lang == "en" else "/") + suffix
def write(path: str, content: str) -> None:
    dest = OUT / path.lstrip("/")
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(content, encoding="utf-8")
def record(lang: str, suffix: str = "") -> None: URLS.append(SITE + route(lang, suffix))

def head(lang: str, suffix: str, title: str, description: str, kind="WebPage", ads=True) -> str:
    url = SITE + route(lang, suffix)
    hreflang = "".join(f"<link rel='alternate' hreflang='{l}' href='{esc(SITE + route(l, suffix))}'>" for l in ("id", "en"))
    hreflang += f"<link rel='alternate' hreflang='x-default' href='{SITE + route('id', suffix)}'>"
    schema = {"@context":"https://schema.org","@type":kind,"name":title,"description":description,"url":url,"inLanguage":lang,"datePublished":DATE,"dateModified":DATE,"author":{"@type":"Organization","name":"Vijeron","url":"https://vijeron.com/"},"publisher":{"@type":"Organization","name":"Vijeron","url":"https://vijeron.com/"},"isPartOf":{"@type":"WebSite","name":"Warna Terukur | Vijeron","url":SITE+"/"}}
    if kind == "Article": schema.update({"headline":title,"mainEntityOfPage":{"@type":"WebPage","@id":url}})
    if kind == "WebApplication": schema.update({"applicationCategory":"UtilityApplication","operatingSystem":"Web"})
    scripts = ("<script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}gtag('consent','default',{ad_storage:'denied',analytics_storage:'denied',ad_user_data:'denied',ad_personalization:'denied',wait_for_update:500});</script><script async src='https://fundingchoicesmessages.google.com/i/pub-6180580801533680?ers=1'></script><script async src='https://www.googletagmanager.com/gtag/js?id=G-79X7K7H4MJ'></script><script>gtag('js',new Date());gtag('config','G-79X7K7H4MJ');</script><script async crossorigin='anonymous' src='https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-6180580801533680'></script>") if ads else ""
    return (f"<!doctype html><html lang='{lang}'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{esc(title)} | Vijeron</title><meta name='description' content='{esc(description)}'><meta name='theme-color' content='#25194a'><link rel='canonical' href='{esc(url)}'>{hreflang}<link rel='icon' type='image/svg+xml' href='/assets/icon.svg'><link rel='stylesheet' href='/assets/site.css'><meta property='og:type' content='{'article' if kind=='Article' else 'website'}'><meta property='og:title' content='{esc(title)}'><meta property='og:description' content='{esc(description)}'><meta property='og:url' content='{esc(url)}'><script type='application/ld+json'>{json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')}</script>{scripts}<script defer src=https://vijeron.com/assets/vijeron-ads.js></script></head><body>")

def chrome(lang: str, suffix: str) -> str:
    t=T[lang]; other="en" if lang=="id" else "id"
    return (f"<a class='skip' href='#main'>{esc(t['skip'])}</a><header class='site-header'><div class='wrap nav-row'><a class='brand' href='{route(lang)}' aria-label='{esc(t['name'])}'><span class='brand-icon' aria-hidden='true'>◒</span><span>WARNA <b>TERUKUR</b><small>BY VIJERON</small></span></a><nav aria-label='{esc(t['guides'])}'><a href='{route(lang)}#panduan'>{esc(t['guides'])}</a><a href='{route(lang)}#alat'>{esc(t['tools'])}</a><a href='{route(lang,'metode/')}'>{esc(t['method'])}</a></nav><div class='lang'><a href='{route(lang,suffix)}' aria-current='page'>{lang.upper()}</a><span>·</span><a href='{route(other,suffix)}'>{other.upper()}</a></div></div></header>")

def footer(lang: str, tools=False) -> str:
    t=T[lang]
    script="<script defer src='/assets/tools.js'></script>" if tools else ""
    return (f"<footer class='site-footer'><div class='wrap footer-row'><div><strong>{esc(t['name'])}</strong><p>{esc(t['footer'])}</p></div><nav><a href='{route(lang,'metode/')}'>{esc(t['method'])}</a><a href='{route(lang,'tentang/')}'>{esc(t['about'])}</a><a href='{route(lang,'privasi/')}'>{esc(t['privacy'])}</a><a href='https://vijeron.com/kontak.html'>{esc(t['contact'])}</a><a href='https://vijeron.com/'>Vijeron.com</a></nav></div></footer>{script}</body></html>")

def references(keys: list[str]) -> str:
    return "<ul class='sources'>"+"".join(f"<li><a href='{esc(SOURCES[k][1])}' rel='noopener noreferrer'>{esc(SOURCES[k][0])} ↗</a></li>" for k in keys)+"</ul>"

def home(lang: str) -> None:
    t=T[lang]
    cards="".join(f"<article class='guide-card'><span class='serial'>{i+1:02d} / 08</span><h3><a href='{route(lang,'panduan/'+g['slug']+'/')}'>{esc(g[lang]['title'])}</a></h3><p>{esc(g[lang]['summary'])}</p><a class='text-link' href='{route(lang,'panduan/'+g['slug']+'/')}'>{esc(t['read'])} ↗</a></article>" for i,g in enumerate(GUIDES))
    art="<div class='color-art' role='img' aria-label='Five overlapping color samples / Lima sampel warna bertumpuk'><div class='swatch swatch-one'>#25194A</div><div class='swatch swatch-two'>#5632A8</div><div class='swatch swatch-three'>#9674DC</div><div class='swatch swatch-four'>#D9CAFF</div><div class='art-caption'>HEX → PAIR → RATIO</div></div>"
    body=(f"<main id='main'><section class='hero'><div class='wrap hero-grid'><div><p class='eyebrow'>VIJERON / COLOR DESK</p><h1>{esc(t['hero'])}</h1><p class='lead'>{esc(t['hero_desc'])}</p><div class='actions'><a class='button' href='{route(lang,'alat/kontras-warna/')}'>{esc(t['start'])} ↗</a><a class='button button-ghost' href='#panduan'>{esc(t['guides'])}</a></div></div>{art}</div></section><section class='wrap principle'><span class='eyebrow'>01 / {esc(t['method'])}</span><h2>{esc(t['principle'])}</h2><p>{esc(t['principle_desc'])}</p></section><section class='tools-block' id='alat'><div class='wrap section'><div class='section-head'><span class='eyebrow'>02 / {esc(t['tools'])}</span><h2>{esc(t['tools_title'])}</h2><p>{esc(t['tools_desc'])}</p></div><div class='tool-grid'><article><span class='serial'>01 / WCAG</span><h3>{esc(t['contrast'])}</h3><p>{esc(t['contrast_desc'])}</p><a href='{route(lang,'alat/kontras-warna/')}'>{esc(t['open'])} ↗</a></article><article><span class='serial'>02 / sRGB</span><h3>{esc(t['palette'])}</h3><p>{esc(t['palette_desc'])}</p><a href='{route(lang,'alat/variasi-warna/')}'>{esc(t['open'])} ↗</a></article></div></div></section><section class='wrap section' id='panduan'><div class='section-head'><span class='eyebrow'>03 / {esc(t['guides'])}</span><h2>{esc(t['guides_title'])}</h2><p>{esc(t['guides_desc'])}</p></div><div class='guide-grid'>{cards}</div></section><section class='wrap editorial'><p>{esc(t['editorial'])}</p><a href='{route(lang,'metode/')}'>{esc(t['method'])} ↗</a></section></main>")
    write(route(lang)+"index.html",head(lang,"",t["name"],t["hero_desc"])+chrome(lang,"")+body+footer(lang));record(lang)

def guide_page(lang: str, guide: dict, index: int) -> None:
    t=T[lang]; item=guide[lang]; suffix="panduan/"+guide["slug"]+"/"; nxt=GUIDES[(index+1)%len(GUIDES)]
    sections="".join(f"<section class='prose-section'><h2>{esc(h)}</h2><p>{esc(p)}</p></section>" for h,p in item["sections"])
    body=(f"<main id='main' class='wrap article-layout'><article><nav class='crumb'><a href='{route(lang)}'>{esc(t['home'])}</a> / {esc(t['guides'])} {index+1:02d}</nav><header class='article-head'><p class='eyebrow'>{esc(t['guides'])} / {index+1:02d}—08</p><h1>{esc(item['title'])}</h1><p class='lead'>{esc(item['summary'])}</p><p class='byline'>Vijeron · {esc(t['updated'])}</p></header><div class='prose'>{sections}<aside class='example'><b>{esc(t['example'])}</b><p>{esc(item['example'])}</p></aside><aside class='caution'><b>{esc(t['caution'])}</b><p>{esc(item['pitfall'])}</p></aside><section class='references'><h2>{esc(t['references'])}</h2>{references(guide['sources'])}</section></div><p class='next'><span>{esc(t['next'])}</span><a href='{route(lang,'panduan/'+nxt['slug']+'/')}'>{esc(nxt[lang]['title'])} ↗</a></p></article><aside class='side-card'><span class='eyebrow'>{esc(t['tools'])}</span><h2>{esc(t['contrast'])}</h2><p>{esc(t['contrast_desc'])}</p><a href='{route(lang,'alat/kontras-warna/')}'>{esc(t['open'])} ↗</a></aside></main>")
    write(route(lang,suffix)+"index.html",head(lang,suffix,item["title"],item["summary"],"Article")+chrome(lang,suffix)+body+footer(lang));record(lang,suffix)

def tool_page(lang: str, kind: str) -> None:
    t=T[lang]; contrast=kind=="kontras-warna"; suffix="alat/"+kind+"/"
    title=t["contrast_title"] if contrast else t["palette_title"]
    intro=t["contrast_intro"] if contrast else t["palette_intro"]
    def hex_field(key,label,value): return f"<label class='field'><span>{esc(label)}</span><input id='{key}' name='{key}' type='text' value='{value}' maxlength='7' pattern='#[0-9A-Fa-f]{{6}}' spellcheck='false' autocomplete='off' required></label>"
    if contrast:
        fields=hex_field("foreground",t["foreground"],"#1E293B")+hex_field("background",t["background"],"#FFFFFF")
    else:
        fields=hex_field("base",t["base"],"#5632A8")+f"<label class='field'><span>{esc(t['step'])}</span><input id='step' name='step' type='number' min='5' max='40' step='1' value='18' required></label>"
    formula=t["contrast_formula"] if contrast else t["palette_formula"]
    limit=t["contrast_limit"] if contrast else t["palette_limit"]
    button=t["calculate"] if contrast else t["generate"]
    related=GUIDES[2] if contrast else GUIDES[6]
    body=(f"<main id='main' class='wrap tool-page'><nav class='crumb'><a href='{route(lang)}'>{esc(t['home'])}</a> / {esc(t['tools'])}</nav><header class='article-head'><p class='eyebrow'>{esc(t['tools'])} / {'01' if contrast else '02'}</p><h1>{esc(title)}</h1><p class='lead'>{esc(intro)}</p></header><div class='calculator-layout'><section class='calc-panel'><form id='calculator' data-tool='{'contrast' if contrast else 'palette'}' data-lang='{lang}'><div class='fields'>{fields}</div><button class='button' type='submit'>{esc(button)} ↗</button></form><div id='result' role='status' aria-live='polite'><h2>{esc(t['result'])}</h2><p>{esc(t['tools_desc'])}</p></div></section><aside class='formula-card'><span class='eyebrow'>{esc(t['formula'])}</span><p>{esc(formula)}</p><p>{esc(limit)}</p><a href='{route(lang,'panduan/'+related['slug']+'/')}'>{esc(related[lang]['title'])} ↗</a></aside></div></main>")
    write(route(lang,suffix)+"index.html",head(lang,suffix,title,intro,"WebApplication")+chrome(lang,suffix)+body+footer(lang,True));record(lang,suffix)

def info_page(lang: str, kind: str) -> None:
    t=T[lang]; key={"metode":"method","tentang":"about","privasi":"privacy"}[kind]; title=t[key+"_title"]; desc=t[key+"_desc"]; suffix=kind+"/"
    if kind=="metode":
        sections=([("Pemeriksa kontras","Alat memakai rumus luminans relatif dan rasio dari WCAG 2.2 untuk dua warna sRGB solid. Keputusan AA memakai rasio penuh sebelum angka tampilan dibulatkan. Pemeriksaan ini tidak menentukan ukuran teks yang sebenarnya atau menilai seluruh antarmuka."),("Variasi warna","Lima variasi dihasilkan dengan aritmetika kanal sRGB terhadap hitam dan putih. Warna hasil bukan campuran cat, prediksi tampilan di semua layar, atau klaim keserasian estetika. Rasio terhadap hitam dan putih ditampilkan agar tiap kandidat dapat ditinjau."),("Editorial dan koreksi","Teks, contoh, dan visual dibuat untuk Vijeron pada 10 Oktober 2026. Tautan W3C memeriksa konsep, bukan menyatakan afiliasi. Kirim koreksi dengan URL halaman melalui kontak portal.")] if lang=="id" else [("Contrast checker","The tool uses WCAG 2.2 relative luminance and ratio for two solid sRGB colors. AA decisions use the full ratio before display rounding. It does not determine actual rendered text size or audit a whole interface."),("Color variations","Five variants use sRGB channel arithmetic toward black and white. Results are not paint mixtures, predictions for every display or aesthetic harmony claims. Ratios against black and white help review each candidate."),("Editorial and corrections","Text, examples and visuals were made for Vijeron on 10 October 2026. W3C links support concepts, not an affiliation. Send corrections with the page URL through the portal contact page.")])
    elif kind=="tentang":
        sections=([("Tujuan","Warna Terukur membantu pembaca membuat keputusan antarmuka yang dapat diuji dan dijelaskan. Situs ini bukan layanan sertifikasi WCAG, agensi desain, atau katalog produk warna."),("Penerbit","Vijeron menerbitkan situs ini sebagai bagian dari katalognya. Organisasi yang dirujuk tidak berafiliasi dengan kami. Iklan tidak mengubah hitungan alat."),("Iklan","Kode Google AdSense ada pada halaman konten. Penayangan bergantung pada status akun dan pilihan privasi; tidak ada janji pendapatan atau posisi iklan.")] if lang=="id" else [("Purpose","Measured Color helps readers make explainable, testable interface decisions. It is not a WCAG certification service, design agency or color product catalogue."),("Publisher","Vijeron publishes this site within its catalog. Referenced organizations are not affiliated with us. Advertising does not alter tool calculations."),("Advertising","Google AdSense code is present on content pages. Serving depends on account status and privacy choices; no revenue or placement is promised.")])
    else:
        sections=([("Data alat","Kode HEX dan langkah variasi dihitung dalam peramban. Situs ini tidak mengirim atau menyimpan nilainya pada server Vijeron."),("Analitik","Google Analytics 4 dapat mencatat tampilan halaman dan peristiwa penggunaan alat. Peristiwa hanya memuat nama alat dan bahasa, tanpa kode warna atau hasil."),("Iklan dan persetujuan","Skrip AdSense dan Funding Choices dapat dimuat pada halaman konten. Penyimpanan iklan dan analitik dimulai ditolak sampai pilihan persetujuan yang berlaku diperoleh. Google dapat memproses data menurut kebijakan layanannya."),("Kontak","Gunakan halaman kontak Vijeron untuk pertanyaan privasi dan koreksi.")] if lang=="id" else [("Tool data","HEX codes and variation steps are calculated in the browser. This site does not transmit or store them on a Vijeron server."),("Analytics","Google Analytics 4 may record page views and tool-use events. Events contain only tool name and language, not color codes or results."),("Ads and consent","AdSense and Funding Choices scripts may load on content pages. Ad and analytics storage start denied until applicable consent choices are obtained. Google may process data under its service policies."),("Contact","Use Vijeron's contact page for privacy questions and corrections.")])
    blocks="".join(f"<section class='prose-section'><h2>{esc(h)}</h2><p>{esc(p)}</p></section>" for h,p in sections)
    refs=f"<section class='references'><h2>{esc(t['references'])}</h2>{references(list(SOURCES))}</section>" if kind=="metode" else ""
    body=f"<main id='main' class='wrap info-page'><nav class='crumb'><a href='{route(lang)}'>{esc(t['home'])}</a> / {esc(title)}</nav><p class='eyebrow'>VIJERON / COLOR DESK</p><h1>{esc(title)}</h1><p class='lead'>{esc(desc)}</p><div class='prose'>{blocks}{refs}</div></main>"
    write(route(lang,suffix)+"index.html",head(lang,suffix,title,desc,ads=kind!="privasi")+chrome(lang,suffix)+body+footer(lang));record(lang,suffix)

def main() -> None:
    if OUT.exists(): shutil.rmtree(OUT)
    (OUT/"assets").mkdir(parents=True)
    for asset in ("site.css","tools.js","icon.svg"): shutil.copy2(ROOT/"assets"/asset,OUT/"assets"/asset)
    for lang in ("id","en"):
        home(lang)
        for index,guide in enumerate(GUIDES): guide_page(lang,guide,index)
        for kind in ("kontras-warna","variasi-warna"): tool_page(lang,kind)
        for kind in ("metode","tentang","privasi"): info_page(lang,kind)
    write("404.html","<!doctype html><html lang='id'><meta charset='utf-8'><title>Halaman tidak ditemukan | Vijeron</title><link rel='stylesheet' href='/assets/site.css'><main class='wrap info-page'><h1>Halaman tidak ditemukan</h1><p>Kembali ke <a href='/'>Warna Terukur</a>.</p></main></html>")
    write("robots.txt",f"User-agent: *\nAllow: /\nSitemap: {SITE}/sitemap.xml\n")
    write("ads.txt","google.com, pub-6180580801533680, DIRECT, f08c47fec0942fa0\n")
    write("_headers","/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: SAMEORIGIN\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Cache-Control: public, max-age=0, must-revalidate\n\n/assets/*\n  Cache-Control: public, max-age=3600, must-revalidate\n\n/sitemap.xml\n  Content-Type: application/xml; charset=utf-8\n\n/ads.txt\n  Content-Type: text/plain; charset=utf-8\n")
    xml=Element("urlset",xmlns="http://www.sitemaps.org/schemas/sitemap/0.9")
    for url in URLS:
        node=SubElement(xml,"url"); SubElement(node,"loc").text=url; SubElement(node,"lastmod").text=DATE
    ElementTree(xml).write(OUT/"sitemap.xml",encoding="utf-8",xml_declaration=True)
    print(f"Built {len(URLS)} public pages in {OUT}")
if __name__=="__main__": main()

